// Chuẩn bị Prompt và Tài liệu đã chuyển thành JSON
// Bạn có thể lấy tài liệu từ các node trước đó (Read PDF, Convert to JSON, Google Drive, v.v.)

const prompt = "Phân tích tài liệu này thành bộ testcase chi tiết gồm: ID, Chức năng, Tiền điều kiện, Các bước thực hiện, Kết quả mong đợi, Phân loại (Positive/Negative).";

const documentJson = {
  "document_name": "26082026_SRS_Thanh toán vé tháng quý qua FW_v1.0",
  "version": "1.0",
  "features": [
    {
      "module": "Thanh toán QR Fintwin",
      "flow": [
        "Hệ thống chuyển hướng sang webview thanh toán QR Fintwin",
        "Khách hàng quét mã QR trên ứng dụng ngân hàng",
        "Xử lý IPN thành công, đồng bộ OCS (CHARGE_METHOD_SELECT = 7)",
        "Hiển thị thông báo mua vé thành công trên App/Web CPT ePass"
      ],
      "exceptions": [
        "Hết thời gian quét QR (Timeout 15 phút)",
        "Giao dịch thất bại do số dư không đủ",
        "Mất kết nối mạng trong quá trình gọi IPN"
      ]
    }
  ]
};

return [{
  json: {
    prompt: prompt,
    document: documentJson,
    newChat: true
  }
}];

// Trích xuất nội dung câu trả lời từ Gemini
const geminiResult = $input.first().json;

return [{
  json: {
    success: geminiResult.success,
    duration: geminiResult.duration,
    testcase_response: geminiResult.response,
    timestamp: geminiResult.timestamp
  }
}];
